const defaultState = {
  user:null,
  users:[],
  sessions:[], articles:[], deduplicationAudits:[], screeningSessions:[], screeningDecisions:[], eligibilityDecisions:[], articleExtractions:[], activities:[], occurrences:[], productValidations:[]
};
let state = load();
state.articleExtractions.forEach(record=>{if(!record.status)record.status="reviewed"});
function load(){try{return {...structuredClone(defaultState),...JSON.parse(localStorage.getItem(DB_KEY)||"{}"),user:null,users:[]} }catch{return structuredClone(defaultState)}}
function save(){localStorage.setItem(DB_KEY,JSON.stringify({...state,user:null,users:[]}));scheduleScientificSync()}
function scientificRecordTime(record){return Math.max(0,...[record.updatedAt,record.decidedAt,record.screenedAt,record.reviewedAt,record.deduplicationConfirmedAt,record.createdAt].map(value=>Date.parse(value)||0))}
function scientificRows(){if(!state.user)return[];return Object.entries(scientificCollections).flatMap(([collection,recordType])=>(state[collection]||[]).filter(record=>!record.owner||record.owner===state.user.id).map(record=>({owner_id:state.user.id,record_type:recordType,record_id:String(record.id),payload:{...record,owner:state.user.id},updated_at:new Date(scientificRecordTime(record)||Date.now()).toISOString()})))}
function scheduleScientificSync(){if(!scientificSyncReady||!state.user||!supabaseClient)return;clearTimeout(scientificSyncTimer);scientificSyncTimer=setTimeout(syncScientificData,700)}
async function syncScientificData(){if(!scientificSyncReady||!state.user||!supabaseClient)return;if(scientificSyncRunning){scientificSyncQueued=true;return}scientificSyncRunning=true;scientificSyncQueued=false;const rows=scientificRows(),currentKeys=new Set(rows.map(row=>`${row.record_type}:${row.record_id}`));try{for(let index=0;index<rows.length;index+=200){const {error}=await supabaseClient.from("scientific_records").upsert(rows.slice(index,index+200),{onConflict:"owner_id,record_type,record_id"});if(error)throw error}const removed=[...scientificCloudKeys].filter(key=>!currentKeys.has(key));for(let index=0;index<removed.length;index+=100){const batch=removed.slice(index,index+100),ids=batch.map(key=>key.slice(key.indexOf(":")+1));const types=[...new Set(batch.map(key=>key.slice(0,key.indexOf(":"))))];for(const type of types){const typeIds=batch.filter(key=>key.startsWith(`${type}:`)).map(key=>key.slice(key.indexOf(":")+1));const {error}=await supabaseClient.from("scientific_records").delete().eq("record_type",type).in("record_id",typeIds);if(error)throw error}}scientificCloudKeys=currentKeys;scientificLastSync=now();scientificSyncError=""}catch(error){scientificSyncError=error.message||"Falha de sincronização";console.error("Falha ao sincronizar dados científicos",error)}finally{scientificSyncRunning=false;if(scientificSyncQueued)scheduleScientificSync()}}
async function loadCloudScientificData(){if(!state.user){scientificSyncReady=false;scientificCloudKeys.clear();return}const {data,error}=await supabaseClient.from("scientific_records").select("record_type,record_id,payload,updated_at");if(error)throw error;scientificCloudKeys=new Set((data||[]).map(row=>`${row.record_type}:${row.record_id}`));for(const [collection,type] of Object.entries(scientificCollections)){const remote=(data||[]).filter(row=>row.record_type===type),local=(state[collection]||[]).filter(record=>!record.owner||record.owner===state.user.id),merged=new Map(remote.map(row=>[String(row.record_id),{record:{...row.payload,owner:state.user.id},cloudTime:Date.parse(row.updated_at)||0}]));local.forEach(record=>{const id=String(record.id),existing=merged.get(id);if(!existing||scientificRecordTime(record)>existing.cloudTime)merged.set(id,{record:{...record,owner:state.user.id},cloudTime:0})});const otherOwners=(state[collection]||[]).filter(record=>record.owner&&record.owner!==state.user.id);state[collection]=[...otherOwners,...[...merged.values()].map(item=>item.record)]}const migrated=backfillLegacyProjectLinks();scientificSyncReady=true;save();scheduleScientificSync();if(migrated)console.info(`EcoMétrica: ${migrated} registro(s) legado(s) vinculado(s) ao projeto único.`)}
function toast(msg){const e=$("#toast");e.textContent=msg;e.classList.add("show");setTimeout(()=>e.classList.remove("show"),2400)}
function activity(type,description,sessionName=""){state.activities.unshift({id:uid(),type,description,sessionName,projectId:activeProjectId||null,createdAt:now(),owner:state.user?.id});save()}
function mine(list){return state.user?.role==="admin"?list:list.filter(x=>x.owner===state.user?.id)}
function download(name,text,type="text/plain"){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function route(){return location.hash.replace(/^#\/?/,"")|| (state.user?"dashboard":"home")}
function go(path){location.hash=`#/${path}`}

