 ["eligibility","Elegibilidade","◎"],["extraction","Matriz de Extração","▤"],["prisma","PRISMA","↳"],["results","Análises","▥"],["vosviewer","VOSviewer","⌘"],["validation","Relatório e validação","◉"]
