const helpGuides={
 dashboard:{title:"Dashboard",intro:"Acompanhe o estado geral do projeto e continue a revisão a partir dos indicadores.",steps:[["Confira o projeto ativo","Verifique no topo se o protocolo correto está selecionado."],["Leia os indicadores","Observe estratégias, artigos, decisões de triagem e ocorrências."],["Acompanhe o progresso","Use a barra para verificar quanto do corpus já foi avaliado."],["Retome o trabalho","Abra sessões ou importe um corpus pelos atalhos do painel."]],tip:"Os números refletem os dados do projeto e do dispositivo atualmente selecionados."},
 projects:{title:"Validação automática do protocolo",subtitle:"Conferência de período, tema e critérios",what:"A Validação Automática examina se o protocolo ativo possui os elementos metodológicos essenciais antes da seleção dos estudos. Ela verifica a estrutura do período, a definição do tema por meio da pergunta e do objetivo geral, e a existência de critérios explícitos de inclusão e exclusão.",purpose:"Serve para identificar lacunas ou inconsistências antes da busca e da triagem. O resultado é apresentado como uma pontuação de 0 a 100%, acompanhada de orientações específicas para corrigir cada item pendente e de uma conferência entre o período do protocolo e as estratégias de busca salvas.",steps:[["Selecione o protocolo ativo","Abra “Projetos e Protocolo” e confirme se o projeto correto está selecionado na lista lateral."],["Defina o período","Informe um ano inicial e um ano final válidos. O início não pode ser posterior ao término."],["Descreva o tema","Preencha claramente a questão de pesquisa e o objetivo geral; esses textos orientam a verificação temática durante a triagem."],["Registre os critérios","Informe ao menos um critério de inclusão e um de exclusão. Prefira um critério por linha para facilitar a leitura e a auditoria."],["Salve o protocolo","A validação utiliza a versão salva e sincronizada. Depois de alterar qualquer campo, clique em “Salvar protocolo”."],["Interprete a pontuação","100% significa que os três componentes estruturais foram preenchidos; 67% indica que um deles requer atenção; valores menores identificam um protocolo incompleto."],["Confira a estratégia de busca","O selo informa se existe uma estratégia salva com o mesmo intervalo de anos do protocolo. Se houver divergência, revise o recorte temporal no Construtor de Busca."],["Registre a validação","Clique em “Registrar validação” para acrescentar ao histórico a data, a pontuação e a quantidade de requisitos atendidos."]],tipLabel:"Atenção metodológica",tip:"A pontuação confirma a presença e a coerência estrutural das informações, mas não certifica a qualidade científica do tema ou dos critérios. A formulação deve continuar sendo revisada pelo pesquisador e, quando possível, pelo orientador ou por um segundo revisor."},
 search:{title:"Construtor de Busca",subtitle:"Montagem de strings para bases científicas",what:"O Construtor de Busca é o coração metodológico da EcoMétrica. É onde você monta, de forma guiada e visual, a string de busca booleana que será usada nas bases científicas — como Web of Science, Scopus e PubMed — para localizar os artigos relevantes à pesquisa.",purpose:"Serve para construir estratégias de busca rigorosas e reproduzíveis, requisito essencial das revisões sistemáticas. A string é formatada para ser utilizada diretamente na base escolhida, respeitando as particularidades de sua sintaxe.",steps:[["Acesse o módulo","Clique em “Construtor de Busca” no menu lateral."],["Escolha a base de dados","Selecione para quais bases a string será formatada, como Web of Science, Scopus ou PubMed. A sintaxe muda automaticamente."],["Configure os filtros em cascata","Defina o escopo geográfico e, para o Brasil, selecione Bioma, Estado, Tipo de organismo, Ambiente e o subtipo aquático aplicável."],["Monte os grupos de descritores","Selecione os blocos de termos-chave. Os sinônimos de cada grupo são combinados com OR; entre os grupos, escolha AND, OR ou NOT."],["Defina os refinamentos","Escolha o idioma dos termos e o recorte temporal da pesquisa."],["Gere e copie a string","Clique em “Gerar strings”. Revise o resultado, copie a estratégia ou acesse diretamente a base científica escolhida."]],tipLabel:"Dica de Ouro",tip:"Ao combinar vários grupos com operadores diferentes, a EcoMétrica preserva automaticamente o agrupamento por parênteses antes de acrescentar os filtros geográficos e biológicos. Isso mantém a precedência lógica correta e evita um dos erros mais comuns em estratégias booleanas manuais."},
 map:{title:"Mapa de Espécies",intro:"Consulte ocorrências georreferenciadas do GBIF e examine sua distribuição espacial.",steps:[["Informe a espécie","Digite o nome científico ou escolha uma seleção rápida."],["Execute a consulta","A EcoMétrica recupera e plota até 300 registros."],["Explore os marcadores","Clique para ver localidade, coordenadas, ambiente e ano."],["Interprete a cobertura","Compare o total encontrado com o número efetivamente plotado."]],tip:"Verifique identificação, precisão geográfica e qualidade temporal dos registros do GBIF."},
 corpus:{title:"Corpus",intro:"Importe os resultados exportados das bases para iniciar uma sessão de análise.",steps:[["Exporte os registros","Prefira BibTeX, RIS ou CSV com metadados completos."],["Selecione os arquivos","É possível combinar exportações de diferentes bases."],["Revise a prévia","Confira quantidade, campos reconhecidos e origem."],["Crie a sessão","O corpus será preparado para deduplicação e triagem."]],tip:"Mantenha os arquivos originais arquivados como evidência da busca realizada."},
 sessions:{title:"Sessões e Deduplicação",intro:"Organize cada importação e audite registros potencialmente duplicados.",steps:[["Abra uma sessão","Confira origem, data e quantidade de artigos."],["Revise os pares candidatos","Compare título, DOI, autores e periódico."],["Decida cada duplicidade","Remova ou mantenha o registro com justificativa auditável."],["Conclua a deduplicação","Somente sessões confirmadas avançam para a triagem."]],tip:"O DOI é um forte identificador, mas títulos normalizados e metadados também devem ser comparados."},
 quality:{title:"Qualidade dos Metadados",intro:"Identifique campos ausentes ou inconsistentes antes das análises cienciométricas.",steps:[["Escolha a sessão","O diagnóstico é calculado para o corpus selecionado."],["Observe a completude","Confira título, autores, ano, DOI, resumo e palavras-chave."],["Examine os problemas","Filtre registros incompletos ou possivelmente duplicados."],["Exporte o diagnóstico","Use o CSV como registro das correções necessárias."]],tip:"A qualidade dos gráficos e redes depende diretamente da padronização dos metadados."},
 screening:{title:"Validação do protocolo na triagem",subtitle:"Apoio à decisão para cada artigo",what:"Durante a triagem, a EcoMétrica compara automaticamente o ano, o título, o resumo e as palavras-chave do artigo com o período e o tema descritos no protocolo vinculado à sessão.",purpose:"Serve como alerta para registros fora do período, sem ano ou com baixa coincidência temática. O painel também apresenta os critérios de inclusão e exclusão exatamente como foram salvos no protocolo, mantendo a decisão rastreável.",steps:[["Confira o protocolo ativo","Verifique o nome do protocolo exibido no painel antes de avaliar o artigo."],["Leia a indicação do período","“Dentro do período” confirma a compatibilidade do ano; “Fora do período” sinaliza divergência; “Ano não informado” exige conferência manual."],["Interprete a aderência temática","“Aderência temática provável” indica coincidência entre os termos do protocolo e os metadados. “Tema requer conferência” não significa exclusão automática."],["Leia o artigo","Examine título, resumo e palavras-chave mesmo quando a indicação automática for favorável."],["Aplique os critérios cadastrados","Use a lista lateral de critérios do protocolo para fundamentar a decisão."],["Registre a decisão","Inclua, exclua ou mantenha o artigo pendente. Toda exclusão deve receber uma justificativa explícita."],["Encaminhe à elegibilidade","Os artigos incluídos seguem automaticamente para avaliação do texto completo."]],tipLabel:"Decisão humana obrigatória",tip:"Os alertas são apoio à triagem e podem ser afetados por resumo ausente, idioma, sinônimos ou metadados incompletos. A EcoMétrica nunca inclui ou exclui um artigo com base apenas nessa verificação automática."},
 eligibility:{title:"Elegibilidade",intro:"Avalie o texto completo dos estudos mantidos após a triagem inicial.",steps:[["Selecione a triagem","Somente artigos aprovados seguem para esta etapa."],["Consulte o texto completo","Verifique população, contexto, método e resultados."],["Decida a elegibilidade","Inclua ou exclua o estudo do corpus final."],["Informe a justificativa","Toda exclusão em texto completo deve possuir motivo explícito."]],tip:"Use critérios definidos previamente e evite excluir estudos apenas por resultados inesperados."},
 extraction:{title:"Matriz de Extração",intro:"Transforme os estudos incluídos em dados estruturados e comparáveis para as análises da dissertação.",steps:[["Selecione a triagem","A matriz recebe somente estudos incluídos após a elegibilidade."],["Pré-preencha as fichas","Use o botão para aproveitar título, resumo, palavras-chave e metadados importados."],["Revise cada sugestão","Compare taxonomia, espécie, ambiente, localidade, impacto, método e manejo com o texto completo."],["Salve a revisão","Somente após salvar a ficha passa de sugestão automática para revisada."],["Exporte a matriz","Baixe o CSV para conferência, análise ou arquivamento."]],tip:"O preenchimento automático reduz o trabalho repetitivo, mas não substitui a leitura do texto completo. Quando um dado não estiver disponível, registre “Não informado” em vez de inferi-lo."},
 prisma:{title:"Diagrama PRISMA 2020",intro:"Visualize e documente o fluxo de identificação, seleção e inclusão dos estudos.",steps:[["Confira os totais","Compare registros identificados, duplicados e triados."],["Revise as exclusões","Os motivos vêm das decisões de triagem e elegibilidade."],["Valide o corpus final","Confirme a soma dos estudos incluídos."],["Baixe o PDF","Gere o diagrama para relatório, dissertação ou artigo."]],tip:"Resolva decisões pendentes antes de exportar para evitar inconsistências."},
 results:{title:"Análise Cienciométrica",intro:"Explore produtividade, impacto, tendências, descritores e estruturas de colaboração do corpus.",steps:[["Escolha sessão e escopo","Defina se a análise usa corpus deduplicado, triado ou incluído."],["Leia os indicadores","Observe produção anual, periódicos, autores e palavras-chave."],["Explore as redes","Passe o mouse ou clique nos nós para destacar relações."],["Analise a produtividade autoral","Na Lei de Lotka, compare a distribuição observada com a referência teórica e examine o expoente estimado."],["Examine a distribuição dos termos","Na Lei de Zipf, compare frequência e posição no ranking para reconhecer concentração e cauda temática."],["Avalie o impacto","Confira citações, documentos citados e índice h do corpus e dos autores."],["Examine instituições e países","Compare produtividade autoral, afiliações, distribuição geográfica e colaboração internacional."],["Compare os períodos","Na evolução temática, observe o ano médio dos nós e os termos emergentes, persistentes ou em declínio."],["Interprete os resultados","Considere cobertura da base, data da coleta e qualidade dos metadados antes de comparar indicadores."]],tip:"Os três períodos são calculados automaticamente a partir dos anos válidos do universo selecionado. Artigos sem ano não participam da comparação temporal."},
 vosviewer:{title:"VOSviewer",intro:"Prepare redes bibliométricas e visualize-as diretamente no navegador.",steps:[["Escolha os dados","Use uma sessão ou arquivo BibTeX, RIS ou CSV."],["Defina a rede","Selecione coautoria ou coocorrência de palavras-chave."],["Ajuste o limite","Eleve o mínimo para reduzir itens muito raros."],["Gere e explore","Passe o mouse ou clique para destacar conexões."],["Exporte ou abra online","Baixe map e network para o VOSviewer oficial."]],tip:"Padronize autores e palavras-chave para evitar nós duplicados por variações de grafia."},
 history:{title:"Histórico auditável",intro:"Consulte a autoria, a data e as versões de cada alteração científica registrada no Supabase.",steps:[["Confira a linha do tempo","Os eventos mais recentes aparecem primeiro, com usuário, horário e ação."],["Filtre os registros","Escolha o tipo de entidade ou procure pelo identificador e pelos campos alterados."],["Examine uma versão","Abra os detalhes para comparar os valores anteriores e posteriores."],["Exporte a auditoria","Baixe o CSV para anexar à documentação metodológica ou arquivar." ]],tip:"O histórico é imutável para os usuários: alterações e exclusões nos dados geram novas entradas, sem apagar as versões anteriores."},
 admin:{title:"Administração",intro:"Gerencie backup, instalação e armazenamento local da EcoMétrica.",steps:[["Exporte backups","Guarde cópias periódicas dos dados científicos."],["Restaure quando necessário","Importe apenas arquivos confiáveis."],["Instale a PWA","Adicione a EcoMétrica ao dispositivo."],["Revise o armazenamento","Confira as quantidades antes de limpar dados."]],tip:"A limpeza é irreversível sem um backup previamente exportado."},
 home:{title:"Primeiros passos",intro:"Conheça o fluxo principal da EcoMétrica antes de iniciar sua revisão.",steps:[["Crie sua conta","Use e-mail ou autenticação Google."],["Cadastre o protocolo","Defina pergunta, objetivos e critérios."],["Construa a busca","Gere strings adaptadas às bases."],["Importe e analise","Siga da deduplicação até PRISMA, resultados e VOSviewer."]],tip:"Uma revisão reprodutível começa com protocolo e estratégia documentados antes da triagem."}
};
