helpGuides.validation={title:"Relatório metodológico e validação",subtitle:"Documentação, usabilidade, acessibilidade e concordância",what:"Este módulo consolida automaticamente o percurso metodológico registrado na EcoMétrica e reúne instrumentos de validação do produto. A existência das funções indica que o desenvolvimento da versão 3.0 foi concluído; a aplicação dos instrumentos com participantes reais constitui uma etapa posterior de validação científica do produto.",purpose:"Serve para documentar o método da revisão, aplicar a Escala de Usabilidade do Sistema (SUS), realizar uma autoavaliação orientada de acessibilidade e medir a concordância entre duas rodadas independentes de seleção.",steps:[["Entenda o estado do produto","“Desenvolvimento concluído” significa que as funcionalidades planejadas estão disponíveis. “Validação pendente” significa apenas que ainda é necessário obter evidências com usuários e revisores reais; não indica erro ou função incompleta."],["Confira o relatório","Selecione a sessão e revise os totais calculados a partir do protocolo, corpus, decisões, extrações e análises."],["Imprima ou salve em PDF","Use o botão do relatório para gerar uma cópia destinada à dissertação ou ao arquivo da pesquisa."],["Aplique o SUS com participantes reais","Depois que cada participante utilizar a plataforma, peça que responda aos dez itens de 1 a 5. Salve uma avaliação por pessoa; a EcoMétrica calculará o resultado agregado."],["Avalie a acessibilidade","Teste teclado, foco, rótulos, descrições, contraste, ampliação, erros e estrutura. Marque Atende, Parcial, Não atende ou Não se aplica e registre navegador, tecnologia assistiva e evidências."],["Prepare duas rodadas independentes","Para medir concordância, dois revisores devem avaliar separadamente os mesmos artigos, sem conhecer previamente a decisão do outro. Registre cada rodada em uma sessão de triagem distinta vinculada ao mesmo corpus."],["Interprete “kappa não calculável”","Essa mensagem aparece quando não existem duas rodadas, quando elas não compartilham artigos já decididos ou quando não há variação suficiente para estimar o acordo ao acaso. Isso é uma condição dos dados, não uma falha do sistema."],["Compare os revisores","Selecione as duas rodadas e relate conjuntamente o número de artigos em comum, o acordo observado, o kappa de Cohen e a matriz Incluir/Excluir."],["Exporte e arquive as evidências","Baixe as avaliações e a concordância em CSV, gere o relatório em PDF e registre versão, data, participantes, equipamentos e procedimentos utilizados."],["Encerre a validação acadêmica","Considere a validação concluída após testar com o público definido no estudo, analisar SUS e acessibilidade, obter duas triagens independentes e documentar resultados e limitações na dissertação."]],tipLabel:"Desenvolvimento x validação",tip:"A EcoMétrica 3.0 pode estar funcionalmente finalizada mesmo antes da coleta com usuários. A validação não adiciona necessariamente novas funções: ela produz evidências de usabilidade, acessibilidade, reprodutibilidade e concordância. O checklist é orientado pela WCAG 2.2, mas não equivale a uma certificação formal."};
function currentHelpKey(){const key=activeNavKey();return helpGuides[key]?key:"home"}
function labelHelpTriggers(){$$(".help-trigger").forEach(button=>{button.textContent="Guia de ajuda";button.setAttribute("aria-label","Abrir guia de ajuda");button.title="Guia de ajuda"})}
function openHelpGuide(){const guide=helpGuides[currentHelpKey()]||helpGuides.home;const overview=guide.what?`<section class="help-overview"><div><b>O que é</b><p>${esc(guide.what)}</p></div><div><b>Para que serve</b><p>${esc(guide.purpose)}</p></div></section>`:`<p class="help-intro">${esc(guide.intro)}</p>`;document.body.insertAdjacentHTML("beforeend",`<div class="help-overlay" id="help-overlay"><aside class="help-drawer" role="dialog" aria-modal="true" aria-labelledby="help-title"><header class="help-header"><div><span>?</span><b>GUIA DE AJUDA</b></div><button type="button" id="close-help" aria-label="Fechar guia">×</button></header><div class="help-body"><h2 id="help-title">${esc(guide.title)}</h2>${guide.subtitle?`<p class="help-subtitle">${esc(guide.subtitle)}</p>`:""}${overview}<span class="help-section-title">Como usar</span><ol class="help-steps">${guide.steps.map(([title,text],index)=>`<li><span>${index+1}</span><div><b>${esc(title)}</b><p>${esc(text)}</p></div></li>`).join("")}</ol><section class="help-tip"><b>💡 ${esc(guide.tipLabel||"Dica metodológica")}</b><p>${esc(guide.tip)}</p></section></div></aside></div>`);const overlay=$("#help-overlay"),close=()=>{overlay.remove();document.body.classList.remove("help-open")};document.body.classList.add("help-open");$("#close-help").onclick=close;overlay.addEventListener("click",event=>{if(event.target===overlay)close()});document.addEventListener("keydown",function escapeHelp(event){if(event.key==="Escape"&&document.body.contains(overlay)){close();document.removeEventListener("keydown",escapeHelp)}});$("#close-help").focus()}
function activeNavKey(){const base=route().split("?")[0].split("/")[0];return base==="session"?"sessions":base==="screen"?"screening":base}
function analysisFlow(active){const current=analysisWorkflow.findIndex(([key])=>key===active);if(current<0)return"";return `<nav class="analysis-flow" aria-label="Fluxo contínuo da análise"><div class="analysis-flow-head"><div><b>Fluxo da análise</b><small>Da criação da sessão ao mapa bibliométrico</small></div><span>Etapa ${current+1} de ${analysisWorkflow.length}</span></div><div class="analysis-flow-track">${analysisWorkflow.map(([key,label,icon],index)=>`<a href="#/${key}" class="analysis-flow-step ${index<current?"complete":index===current?"current":"upcoming"}" ${index===current?'aria-current="step"':""}><span>${index<current?"✓":icon}</span><b>${label}</b><small>${index+1}</small></a>`).join("")}</div></nav>`}

function appFooter(){return `<footer class="footer"><img class="footer-logo" src="icons/decb-uern.png" alt="Logomarca do Departamento de Ciências Biológicas da UERN"><div>Universidade do Estado do Rio Grande do Norte — UERN © 2026</div><div>Desenvolvido pelo Prof. José Egberto Mesquita Pinto Júnior com a ferramenta de IA ChatGPT</div><div class="footer-actions"><span class="footer-version" aria-label="Versão da EcoMétrica">EcoMétrica 3.0 · Versão 86</span><button type="button" class="footer-cite-button" id="cite-ecometrica">Como citar a EcoMétrica</button></div></footer>`}
function citationAccessDate(){return new Intl.DateTimeFormat("pt-BR",{day:"2-digit",month:"short",year:"numeric"}).format(new Date()).replaceAll(" de "," ").replace(".","")}
function ecometricaCitations(){const accessed=citationAccessDate(),iso=new Date().toISOString().slice(0,10),url="https://egbertomesquita-cmd.github.io/ecometrica-pwa/",title="EcoMétrica 3.0: plataforma cienciométrica para revisões sistemáticas e análise da biodiversidade";return {abnt:`PINTO JÚNIOR, José Egberto Mesquita. ${title}. Versão 86. Mossoró: Universidade do Estado do Rio Grande do Norte, 2026. Software. Disponível em: ${url}. Acesso em: ${accessed}.`,apa:`Pinto Júnior, J. E. M. (2026). ${title} (Version 86) [Computer software]. Universidade do Estado do Rio Grande do Norte. ${url}`,vancouver:`Pinto Júnior JEM. ${title} [software]. Version 86. Mossoró: Universidade do Estado do Rio Grande do Norte; 2026 [cited ${accessed}]. Available from: ${url}`,chicago:`Pinto Júnior, José Egberto Mesquita. 2026. “${title}.” Version 86. Computer software. Mossoró: Universidade do Estado do Rio Grande do Norte. ${url}.`,bibtex:`@software{pinto_junior_ecometrica_2026,\n  author    = {Pinto Júnior, José Egberto Mesquita},\n  title     = {${title}},\n  version   = {86},\n  year      = {2026},\n  publisher = {Universidade do Estado do Rio Grande do Norte},\n  address   = {Mossoró, RN},\n  url       = {${url}},\n  urldate   = {${iso}}\n}`}}
function openCitationGenerator(){const citations=ecometricaCitations();document.body.insertAdjacentHTML("beforeend",`<div class="modal" id="citation-modal" role="dialog" aria-modal="true" aria-labelledby="citation-title"><section class="card citation-modal-card"><div class="citation-heading"><div><span class="eyebrow">Referência do software</span><h2 id="citation-title">Como citar a EcoMétrica</h2></div><button type="button" class="citation-close" id="close-citation" aria-label="Fechar">×</button></div><p class="muted">Escolha um dos estilos bibliográficos mais utilizados. A referência inclui autor, instituição, versão, endereço eletrônico e data de acesso.</p><div class="field"><label for="citation-style">Modelo de referência</label><select id="citation-style"><option value="abnt">ABNT NBR 6023</option><option value="apa">APA — 7ª edição</option><option value="vancouver">Vancouver</option><option value="chicago">Chicago — autor-data</option><option value="bibtex">BibTeX</option></select></div><div class="citation-preview" id="citation-preview" tabindex="0">${esc(citations.abnt)}</div><div class="actions"><button type="button" class="btn btn-outline" id="cancel-citation">Fechar</button><button type="button" class="btn btn-primary" id="copy-citation">Copiar referência</button></div><small class="muted citation-note">Confira as exigências específicas do periódico ou da instituição antes da submissão.</small></section></div>`);const modal=$("#citation-modal"),select=$("#citation-style"),preview=$("#citation-preview");const close=()=>modal.remove();select.addEventListener("change",()=>{preview.textContent=citations[select.value]});$("#close-citation").onclick=close;$("#cancel-citation").onclick=close;modal.addEventListener("click",event=>{if(event.target===modal)close()});document.addEventListener("keydown",function escapeCitation(event){if(event.key==="Escape"&&document.body.contains(modal)){close();document.removeEventListener("keydown",escapeCitation)}});$("#copy-citation").onclick=async()=>{try{await navigator.clipboard.writeText(preview.textContent);toast("Referência copiada.")}catch{const range=document.createRange();range.selectNodeContents(preview);const selection=getSelection();selection.removeAllRanges();selection.addRange(range);toast("Referência selecionada. Use Copiar.")}};select.focus()}
function landing(){return `<div class="landing"><header class="public-nav"><div class="brand"><img src="icons/icon.svg" alt=""><span>EcoMétrica</span></div><div class="actions"><button class="btn btn-outline help-trigger" type="button">Guia de ajuda</button><button class="btn btn-outline" data-go="login">Entrar</button><button class="btn btn-primary" data-go="register">Criar conta</button></div></header><main><section class="hero"><div class="institutional-brands" aria-label="Instituições responsáveis"><div class="ppgcn-brand"><img src="icons/ppgcn.png" alt="Símbolo do Programa de Pós-Graduação em Ciências Naturais"><span><b>PPGCN</b><small>Programa de Pós-Graduação em Ciências Naturais</small></span></div><span class="brand-divider" aria-hidden="true"></span><img class="uern-brand" src="icons/uern-branca.png" alt="Universidade do Estado do Rio Grande do Norte — UERN"></div><h1>Plataforma Cienciométrica para Espécies Invasoras</h1><p>Ferramenta de revisão bibliográfica sistemática sobre espécies animais exóticas invasoras em ambientes aquáticos continentais da Caatinga, com foco no Rio Grande do Norte.</p><div class="actions"><button class="btn btn-primary" data-go="register">Começar revisão</button><button class="btn btn-outline" data-go="login">Já tenho acesso</button></div></section><section class="features">${[["Triagem Sistemática","Avalie títulos e resumos com critérios transparentes."],["Diagrama PRISMA","Acompanhe cada etapa da seleção de estudos."],["Análise Cienciométrica","Explore tendências, autores, periódicos e descritores."],["Mapa de Ocorrências","Consulte registros públicos de espécies via GBIF."]].map(x=>`<article class="feature"><span class="eyebrow">${x[0]}</span><b>${x[0]}</b><p>${x[1]}</p></article>`).join("")}</section></main>${appFooter()}</div>`}
function authPage(kind){const reg=kind==="register";return `<div class="auth-wrap"><form class="card auth-card" id="auth-form"><div class="brand"><img src="icons/icon.svg" alt=""><span>EcoMétrica</span></div><h1>${reg?"Criar conta":"Bem-vindo de volta"}</h1><p class="muted">${reg?"Cadastre-se para iniciar sua revisão.":"Entre com sua conta segura."}</p><button type="button" class="btn btn-google" id="google-login"><span class="google-mark" aria-hidden="true">G</span>Continuar com Google</button><div class="auth-divider"><span>ou use seu e-mail</span></div>${reg?`<div class="field"><label>Nome</label><input name="name" required autocomplete="name"></div>`:""}<div class="field"><label>E-mail</label><input name="email" type="email" required autocomplete="email"></div><div class="field"><label>Senha</label><input name="password" type="password" minlength="8" required autocomplete="${reg?"new-password":"current-password"}"></div>${reg?`<div class="field"><label>Instituição</label><input name="institution" value="PPGCN/UERN" autocomplete="organization"></div>`:""}<button type="submit" class="btn btn-primary" style="width:100%">${reg?"Criar conta":"Entrar"}</button><p class="auth-switch">${reg?`Já possui uma conta? <a href="#/login">Entrar</a>`:`Ainda não possui uma conta? <a href="#/register">Criar conta</a>`}</p><button type="button" class="btn btn-outline" style="width:100%;margin-top:8px" data-go="home">Voltar</button></form></div>`}

function activeProject(){return cloudProjects.find(p=>p.id===activeProjectId)||null}
function sessionProjectId(sessionId){return state.sessions.find(session=>session.id===sessionId)?.projectId||null}
function screeningProjectId(screeningId){const screening=state.screeningSessions.find(item=>item.id===screeningId);return screening?.projectId||sessionProjectId(screening?.analysisSessionId)||null}
function articleProjectId(articleId){const article=state.articles.find(item=>item.id===articleId);return article?.projectId||sessionProjectId(article?.sessionId)||null}
function analysisProjectId(articles=[]){return articles.map(article=>article.projectId||sessionProjectId(article.sessionId)).find(Boolean)||null}
function recordsForProject(list,projectId=activeProjectId){return mine(list).filter(record=>projectId&&record.projectId===projectId)}
function backfillLegacyProjectLinks(){if(!state.user||cloudProjects.length!==1)return 0;const projectId=cloudProjects[0].id,owned=record=>!record.owner||record.owner===state.user.id;let changed=0;const assign=(record,id=projectId)=>{if(record&&owned(record)&&!record.projectId&&id){record.projectId=id;record.updatedAt=now();changed++}};state.sessions.forEach(record=>assign(record));state.articles.forEach(record=>assign(record,sessionProjectId(record.sessionId)));state.deduplicationAudits.forEach(record=>assign(record,sessionProjectId(record.sessionId)));state.screeningSessions.forEach(record=>assign(record,sessionProjectId(record.analysisSessionId)));state.screeningDecisions.forEach(record=>assign(record,screeningProjectId(record.screeningSessionId)||articleProjectId(record.articleId)));state.eligibilityDecisions.forEach(record=>assign(record,screeningProjectId(record.screeningSessionId)||articleProjectId(record.articleId)));state.articleExtractions.forEach(record=>assign(record,screeningProjectId(record.screeningSessionId)||articleProjectId(record.articleId)));state.occurrences.forEach(record=>assign(record));state.productValidations.forEach(record=>assign(record,sessionProjectId(record.sessionId)||projectId));state.activities.forEach(record=>assign(record));return changed}
function shell(content){const active=activeNavKey(),project=activeProject(),context=project?`${esc(project.title)} · ${project.start_year}–${project.end_year}`:"Nenhum projeto ativo";return `<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><img src="icons/icon.svg" alt=""><span>EcoMétrica</span></div><nav>${nav.filter(x=>x[0]!=="admin"||state.user.role==="admin").map(([p,l,i])=>`<a href="#/${p}" class="nav-link ${active===p?"active":""}" ${active===p?'aria-current="page"':""}><span>${i}</span> ${l}</a>`).join("")}</nav><div class="sidebar-foot">PPGCN/UERN<br>${project?`Projeto ativo: ${esc(project.title)}`:"Selecione um projeto"}<br><small>Protocolos sincronizados</small></div></aside><section class="app-main"><header class="topbar"><button class="menu-toggle" id="menu-toggle" aria-label="Abrir menu">☰</button><div class="topbar-context"><small>Projeto ativo</small><span>${context}</span></div><div class="user-chip"><button class="topbar-icon help-trigger" type="button" aria-label="Abrir ajuda" title="Ajuda">?</button><span class="avatar">${esc(state.user.name.slice(0,2).toUpperCase())}</span><span class="user-text"><b>${esc(state.user.name)}</b><small>${state.user.role==="admin"?"Administrador":"Pesquisador"}</small></span><button class="topbar-exit" id="logout" type="button">Sair</button></div></header><main class="content">${analysisFlow(active)}${content}</main>${appFooter()}</section></div>`}
function head(title,desc,actions=""){const validation=title==="Projetos e Protocolo"&&activeProject()?protocolValidationPanel(activeProject()):"";return `<header class="page-head"><div class="toolbar" style="justify-content:space-between"><div><h1>${title}</h1><p>${desc}</p></div>${actions}</div></header>${validation}`}
function empty(title,text,button=""){return `<div class="card empty"><h2>${title}</h2><p class="muted">${text}</p>${button}</div>`}

function dashboard(){const project=activeProject(),sessions=recordsForProject(state.sessions),articles=recordsForProject(state.articles),decisions=recordsForProject(state.screeningDecisions),occ=recordsForProject(state.occurrences);const screened=decisions.filter(x=>x.decision!=="pending").length,total=decisions.length,progress=total?Math.round(screened/total*100):0,strategies=project?cloudStrategies.filter(x=>x.project_id===project.id).length:0;return `${head("Dashboard","Visão geral da revisão sistemática e de seu protocolo de pesquisa.")} ${project?`<section class="card project-context"><div><span class="eyebrow">Projeto ativo</span><h2>${esc(project.title)}</h2><p>${esc(project.research_question||"Questão de pesquisa ainda não informada.")}</p></div><div class="project-context-actions"><span class="badge green">${project.start_year}–${project.end_year}</span><button class="btn btn-outline btn-sm" data-go="projects">Ver protocolo</button></div></section>`:`<section class="notice project-empty"><b>Comece pelo protocolo da pesquisa.</b> Crie um projeto para registrar objetivos, critérios e versões das buscas. <button class="btn btn-primary btn-sm" data-go="projects">Criar projeto</button></section>`}<section class="grid metrics"><article class="card metric"><small>Estratégias salvas</small><div class="value">${strategies}</div></article><article class="card metric"><small>Artigos no corpus</small><div class="value">${articles.filter(x=>!x.isDuplicate).length}</div></article><article class="card metric"><small>Artigos triados</small><div class="value">${screened}</div></article><article class="card metric"><small>Ocorrências GBIF</small><div class="value">${occ.length}</div></article></section><section class="grid two-col" style="margin-top:16px"><article class="card"><h2>Progresso da triagem</h2><div class="progress"><span style="width:${progress}%"></span></div><p><b>${progress}%</b> · ${screened} de ${total||0} registros avaliados</p>${sessions.length?`<button class="btn btn-primary" data-go="sessions">Ver sessões</button>`:`<div class="notice">Crie sua primeira sessão importando um corpus bibliográfico.</div><button class="btn btn-primary" data-go="corpus" style="margin-top:12px">Importar corpus</button>`}</article><article class="card"><h2>Atividades recentes</h2>${recordsForProject(state.activities).slice(0,6).map(a=>`<p><b>${esc(a.description)}</b><br><small class="muted">${new Date(a.createdAt).toLocaleString("pt-BR")}</small></p>`).join("")||`<p class="muted">Nenhuma atividade registrada.</p>`}</article></section>`}

async function loadCloudResearchData(){
 if(!state.user){cloudProjects=[];cloudStrategies=[];cloudExecutions=[];cloudAuditHistory=[];activeProjectId="";return}
 const [projectsResult,strategiesResult,executionsResult,auditResult]=await Promise.all([
  supabaseClient.from("research_projects").select("*").order("updated_at",{ascending:false}),
  supabaseClient.from("search_strategies").select("*").order("created_at",{ascending:false}),
  supabaseClient.from("search_executions").select("*").order("executed_at",{ascending:false}),
  supabaseClient.from("audit_history").select("*").order("created_at",{ascending:false}).limit(2000)
 ]);
 const error=projectsResult.error||strategiesResult.error||executionsResult.error||auditResult.error;if(error)throw error;
 cloudProjects=projectsResult.data||[];cloudStrategies=strategiesResult.data||[];cloudExecutions=executionsResult.data||[];cloudAuditHistory=auditResult.data||[];
 if(!cloudProjects.some(p=>p.id===activeProjectId))activeProjectId=cloudProjects[0]?.id||"";
 if(activeProjectId)localStorage.setItem(ACTIVE_PROJECT_KEY,activeProjectId);else localStorage.removeItem(ACTIVE_PROJECT_KEY)
}
function lines(value){return Array.isArray(value)?value.join("\n"):""}
function dbChecks(selected=[]){return Object.entries(databases).map(([id,d])=>`<label class="protocol-check"><input type="checkbox" name="project_db" value="${id}" ${selected.includes(id)?"checked":""}> <span><b>${d[0]}</b><small>${d[4]}</small></span></label>`).join("")}
function criterionItems(value){return String(value||"").split(/\n+|;(?=\s*[A-ZÀ-Ú])/).map(item=>item.replace(/^[-•\d.)\s]+/,"").trim()).filter(Boolean)}
function protocolValidation(project){
 const start=Number(project?.start_year),end=Number(project?.end_year),inclusion=criterionItems(project?.inclusion_criteria),exclusion=criterionItems(project?.exclusion_criteria),question=String(project?.research_question||"").trim(),objective=String(project?.general_objective||"").trim();
 const periodOk=Number.isInteger(start)&&Number.isInteger(end)&&start>=1900&&end<=2100&&start<=end,themeOk=question.length>=20&&objective.length>=20,criteriaOk=inclusion.length>0&&exclusion.length>0;
 const checks=[{key:"period",label:"Período",ok:periodOk,detail:periodOk?`${start}–${end} definido de forma válida.`:"Informe anos válidos e mantenha o ano inicial anterior ao final."},{key:"theme",label:"Tema e pergunta",ok:themeOk,detail:themeOk?"Questão de pesquisa e objetivo geral estão documentados.":"Preencha a questão de pesquisa e o objetivo geral com clareza."},{key:"criteria",label:"Critérios",ok:criteriaOk,detail:criteriaOk?`${inclusion.length} critério(s) de inclusão e ${exclusion.length} de exclusão definidos.`:"Registre ao menos um critério de inclusão e um de exclusão."}];
 const passed=checks.filter(check=>check.ok).length,score=Math.round(passed/checks.length*100),strategies=project?cloudStrategies.filter(strategy=>strategy.project_id===project.id):[],matchingStrategy=periodOk&&strategies.some(strategy=>Number(strategy.start_year)===start&&Number(strategy.end_year)===end);
 return {checks,passed,score,inclusion,exclusion,periodOk,themeOk,criteriaOk,strategies,matchingStrategy,status:score===100?"validated":score>=67?"attention":"incomplete"}
}
const protocolStopWords=new Set("para como uma umas uns dos das de do da em no na nos nas por pelo pela que qual quais onde quando entre sobre com sem seu sua seus suas este esta esses essas estudo estudos pesquisa objetivo analisar avaliar investigar verificar compreender identificar relação relacao efeitos impacto artigos article study research the and for with from into this that these those review".split(" "));
function protocolThemeTerms(project){const source=norm(`${project?.title||""} ${project?.research_question||""} ${project?.general_objective||""}`);return [...new Set(source.split(" ").filter(word=>word.length>=4&&!protocolStopWords.has(word)&&!/^\d+$/.test(word)))]}
function articleProtocolCheck(article,project){
 if(!project)return {period:"unknown",theme:"unknown",matches:[],summary:"Nenhum protocolo foi vinculado a esta triagem."};
 const year=Number(article?.year),period=!year?"unknown":year>=Number(project.start_year)&&year<=Number(project.end_year)?"pass":"fail",terms=protocolThemeTerms(project),articleText=norm(`${article?.title||""} ${article?.abstract||""} ${article?.keywords||""}`),matches=terms.filter(term=>articleText.includes(term)),theme=!articleText||!terms.length?"unknown":matches.length>=Math.min(3,Math.max(1,Math.ceil(terms.length*.12)))?"pass":"attention";
 return {period,theme,matches:matches.slice(0,8),summary:period==="fail"?`O ano ${year} está fora do período ${project.start_year}–${project.end_year}.`:period==="unknown"?"O registro não informa ano; confira o texto ou a base de origem.":"O ano do registro está dentro do período do protocolo."}
}
function protocolValidationPanel(project){if(!project)return `<section class="notice protocol-validation-empty"><b>Validação indisponível.</b> Salve o protocolo para conferir período, tema e critérios.</section>`;const report=protocolValidation(project),label=report.status==="validated"?"Protocolo validado":report.status==="attention"?"Requer atenção":"Protocolo incompleto";return `<section class="card protocol-validation ${report.status}"><div class="protocol-validation-head"><div><span class="eyebrow">Validação automática</span><h2>${label}</h2><p>Conferência estrutural do período, tema e critérios definidos.</p></div><div class="protocol-score" aria-label="${report.score}% dos requisitos atendidos"><strong>${report.score}%</strong><small>${report.passed}/3 itens</small></div></div><div class="protocol-checks">${report.checks.map(check=>`<article class="protocol-validation-item ${check.ok?"pass":"fail"}"><span aria-hidden="true">${check.ok?"✓":"!"}</span><div><b>${check.label}</b><p>${esc(check.detail)}</p></div></article>`).join("")}</div><div class="protocol-validation-foot"><span class="badge ${report.matchingStrategy?"green":"amber"}">${report.matchingStrategy?"Busca compatível com o período":"Estratégia de busca ainda não validada para este período"}</span><button class="btn btn-outline btn-sm" type="button" id="validate-protocol">Registrar validação</button></div><small class="muted">A validação verifica a estrutura do protocolo. A pertinência científica dos critérios continua sob responsabilidade do pesquisador.</small></section>`}
function screeningProtocolProject(screening){return cloudProjects.find(project=>project.id===screening?.projectId)||activeProject()}
function injectScreeningProtocolValidation(){
 const [section,id]=route().split("/");if(section!=="screen"||!id)return;const screening=state.screeningSessions.find(item=>item.id===id),decision=state.screeningDecisions.find(item=>item.screeningSessionId===id&&item.decision==="pending"),article=decision&&state.articles.find(item=>item.id===decision.articleId),project=screeningProtocolProject(screening),workspace=$(".article-focus")?.parentElement;if(!workspace||!article)return;
 const report=project?protocolValidation(project):null,check=articleProtocolCheck(article,project),periodLabel=check.period==="pass"?"Dentro do período":check.period==="fail"?"Fora do período":"Ano não informado",themeLabel=check.theme==="pass"?"Aderência temática provável":check.theme==="attention"?"Tema requer conferência":"Metadados insuficientes",panel=document.createElement("section");panel.className="card article-protocol-validation";panel.innerHTML=`<div class="article-protocol-head"><div><span class="eyebrow">Protocolo ativo</span><h3>${esc(project?.title||"Protocolo não vinculado")}</h3></div><span class="badge ${report?.score===100?"green":"amber"}">${report?`${report.score}% estruturado`:"Não validado"}</span></div><div class="article-protocol-status"><div class="${check.period==="pass"?"pass":check.period==="fail"?"fail":"unknown"}"><b>${periodLabel}</b><small>${esc(check.summary)}</small></div><div class="${check.theme==="pass"?"pass":check.theme==="attention"?"warn":"unknown"}"><b>${themeLabel}</b><small>${check.matches.length?`Termos coincidentes: ${esc(check.matches.join(", "))}.`:"Confira título, resumo e palavras-chave em relação ao tema."}</small></div></div><p class="protocol-assistance"><b>Apoio à decisão:</b> a indicação é automática e não inclui nem exclui o artigo. Aplique os critérios registrados e justifique a decisão.</p>`;workspace.parentElement.insertBefore(panel,workspace);
 const criteriaAside=$(".article-focus + aside");if(criteriaAside&&project){criteriaAside.innerHTML=`<h3>Critérios de inclusão do protocolo</h3>${report.inclusion.length?`<ul>${report.inclusion.map(item=>`<li>${esc(item)}</li>`).join("")}</ul>`:'<p class="muted">Não definidos.</p>'}<h3>Critérios de exclusão do protocolo</h3>${report.exclusion.length?`<ul>${report.exclusion.map(item=>`<li>${esc(item)}</li>`).join("")}</ul>`:'<p class="muted">Não definidos.</p>'}`}
}
function projectsPage(){
 const current=creatingProject?null:activeProject(),strategies=current?cloudStrategies.filter(x=>x.project_id===current.id):[],executions=current?cloudExecutions.filter(x=>x.project_id===current.id):[];
 const projectList=cloudProjects.map(p=>`<button type="button" class="project-list-item ${p.id===activeProjectId&&!creatingProject?"active":""}" data-project-id="${p.id}"><b>${esc(p.title)}</b><small>${p.start_year}–${p.end_year} · ${p.status==="active"?"Ativo":p.status==="draft"?"Rascunho":"Arquivado"}</small></button>`).join("")||`<p class="muted">Nenhum projeto cadastrado.</p>`;
 const history=strategies.map(s=>{const runs=executions.filter(x=>x.strategy_id===s.id);return `<article class="card strategy-history"><div class="toolbar"><div><span class="eyebrow">Versão ${s.version}</span><h3>${esc(s.title)}</h3><small class="muted">${new Date(s.created_at).toLocaleString("pt-BR")} · ${(s.selected_databases||[]).map(id=>databases[id]?.[0]||id).join(", ")}</small></div></div><p>${esc(s.notes||"Sem observações.")}</p><details><summary>Ver strings registradas</summary>${Object.entries(s.generated_queries||{}).map(([id,q])=>`<h4>${esc(databases[id]?.[0]||id)}</h4><pre class="saved-query">${esc(q)}</pre>`).join("")}</details><form class="execution-form" data-strategy-id="${s.id}"><div class="field"><label>Base consultada</label><select name="database_id">${(s.selected_databases||[]).map(id=>`<option value="${id}">${esc(databases[id]?.[0]||id)}</option>`).join("")}</select></div><div class="field"><label>Resultados encontrados</label><input type="number" name="result_count" min="0" placeholder="Ex.: 248"></div><div class="field"><label>Observação</label><input name="notes" placeholder="Data, filtros ou ajustes realizados"></div><button class="btn btn-outline btn-sm" type="submit">Registrar execução</button></form>${runs.length?`<div class="run-list">${runs.map(r=>`<small><b>${esc(databases[r.database_id]?.[0]||r.database_id)}</b> · ${r.result_count??"quantidade não informada"} · ${new Date(r.executed_at).toLocaleString("pt-BR")}${r.notes?` · ${esc(r.notes)}`:""}</small>`).join("")}</div>`:""}</article>`}).join("");
 return `${head("Projetos e Protocolo","Registre o planejamento metodológico e preserve o histórico reproduzível de cada busca.",'<button class="btn btn-primary" id="new-project">Novo projeto</button>')}<section class="protocol-layout"><aside class="card project-list"><h2>Meus projetos</h2>${projectList}</aside><div><form id="project-form" class="card protocol-form"><input type="hidden" name="id" value="${current?.id||""}"><div class="toolbar"><div><span class="eyebrow">${current?"Protocolo ativo":"Novo protocolo"}</span><h2>${current?esc(current.title):"Criar projeto de pesquisa"}</h2></div><button class="btn btn-primary" type="submit">Salvar protocolo</button></div><div class="field"><label>Título do projeto *</label><input name="title" required value="${esc(current?.title||"")}" placeholder="Ex.: Espécies exóticas invasoras em ambientes aquáticos"></div><div class="field"><label>Questão de pesquisa</label><textarea name="research_question" rows="3" placeholder="Qual pergunta orientará a revisão?">${esc(current?.research_question||"")}</textarea></div><div class="field"><label>Objetivo geral</label><textarea name="general_objective" rows="3">${esc(current?.general_objective||"")}</textarea></div><div class="field"><label>Objetivos específicos</label><textarea name="specific_objectives" rows="5" placeholder="Informe um objetivo por linha">${esc(lines(current?.specific_objectives))}</textarea></div><div class="grid two-col"><div class="field"><label>Ano inicial</label><input type="number" name="start_year" min="1900" max="2100" value="${current?.start_year||2004}" required></div><div class="field"><label>Ano final</label><input type="number" name="end_year" min="1900" max="2100" value="${current?.end_year||2025}" required></div></div><div class="grid two-col"><div class="field"><label>Critérios de inclusão</label><textarea name="inclusion_criteria" rows="6">${esc(current?.inclusion_criteria||"")}</textarea></div><div class="field"><label>Critérios de exclusão</label><textarea name="exclusion_criteria" rows="6">${esc(current?.exclusion_criteria||"")}</textarea></div></div><fieldset><legend>Bases de dados previstas</legend><div class="protocol-databases">${dbChecks(current?.selected_databases||[])}</div></fieldset><div class="grid two-col"><div class="field"><label>Instituição</label><input name="institution" value="${esc(current?.institution||state.user.institution||"PPGCN/UERN")}"></div><div class="field"><label>Status</label><select name="status"><option value="active" ${current?.status==="active"?"selected":""}>Ativo</option><option value="draft" ${current?.status==="draft"?"selected":""}>Rascunho</option><option value="archived" ${current?.status==="archived"?"selected":""}>Arquivado</option></select></div></div></form>${current?`<section class="protocol-history"><div class="toolbar"><div><h2>Histórico de buscas</h2><p class="muted">Versões imutáveis das estratégias e registros das consultas realizadas.</p></div><button class="btn btn-outline" data-go="search">Criar nova estratégia</button></div>${history||empty("Nenhuma estratégia salva","Gere uma string no Construtor de Busca e salve-a neste projeto.")}</section>`:""}</div></section>`
}
async function saveProject(form){const f=new FormData(form),id=String(f.get("id")||""),start=Number(f.get("start_year")),end=Number(f.get("end_year"));if(start>end)return toast("O ano inicial deve ser anterior ao ano final.");const payload={owner_id:state.user.id,title:String(f.get("title")).trim(),research_question:String(f.get("research_question")||"").trim(),general_objective:String(f.get("general_objective")||"").trim(),specific_objectives:String(f.get("specific_objectives")||"").split(/\n+/).map(x=>x.trim()).filter(Boolean),start_year:start,end_year:end,inclusion_criteria:String(f.get("inclusion_criteria")||"").trim(),exclusion_criteria:String(f.get("exclusion_criteria")||"").trim(),selected_databases:f.getAll("project_db"),institution:String(f.get("institution")||"").trim(),status:f.get("status"),updated_at:now()};const button=form.querySelector('button[type="submit"]');button.disabled=true;button.textContent="Salvando…";const result=id?await supabaseClient.from("research_projects").update(payload).eq("id",id).select().single():await supabaseClient.from("research_projects").insert(payload).select().single();if(result.error){button.disabled=false;button.textContent="Salvar protocolo";return toast(`Não foi possível salvar: ${result.error.message}`)}activeProjectId=result.data.id;creatingProject=false;localStorage.setItem(ACTIVE_PROJECT_KEY,activeProjectId);await loadCloudResearchData();toast("Protocolo salvo e sincronizado.");render()}
async function saveExecution(form){const f=new FormData(form),project=activeProject();if(!project)return;const count=String(f.get("result_count")||"").trim();const {error}=await supabaseClient.from("search_executions").insert({project_id:project.id,strategy_id:form.dataset.strategyId,owner_id:state.user.id,database_id:f.get("database_id"),result_count:count===""?null:Number(count),notes:String(f.get("notes")||"").trim(),executed_at:now()});if(error)return toast(`Não foi possível registrar: ${error.message}`);await loadCloudResearchData();toast("Execução registrada no histórico.");render()}

