function qualityTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Registro</th><th>Metadados</th><th>Ocorrências</th></tr></thead><tbody>${rows.slice(0,300).map(row=>`<tr><td><b>${esc(row.article.title||"Sem título")}</b><small>${esc(row.article.authors||"Autores não informados")}</small></td><td><small>${row.article.year||"—"} · ${esc(row.article.journal||row.article.source||"Fonte não informada")}</small><br><small>DOI: ${esc(row.article.doi||"—")}</small></td><td><div class="quality-tags">${row.issues.map(issue=>`<span class="badge ${issue==="DOI inválido"||issue==="Possível duplicidade"?"amber":""}">${esc(issue)}</span>`).join("")}</div></td></tr>`).join("")}</tbody></table></div>`:`<div class="empty"><h3>Nenhuma ocorrência encontrada</h3><p class="muted">Todos os registros atendem aos critérios do diagnóstico.</p></div>`}
