function exportDedupAudit(sessionId){const session=state.sessions.find(s=>s.id===sessionId),audits=ensureDedupAudits(sessionId),header=["audit_id","sessao","regra","justificativa","confianca","decisao","titulo_principal","doi_principal","titulo_comparado","doi_comparado","revisor","data_decisao","observacao"],rows=audits.map(a=>{const p=state.articles.find(x=>x.id===a.primaryArticleId)||{},d=state.articles.find(x=>x.id===a.duplicateArticleId)||{};return [a.id,session.name,a.rule,a.reason,a.confidence,a.decision,p.title,p.doi,d.title,d.doi,a.reviewerName,a.decidedAt,a.note]});download(`auditoria-deduplicacao-${norm(session.name).replaceAll(" ","-")||"sessao"}.csv`,[header,...rows].map(row=>row.map(v=>`"${String(v??"").replaceAll('"','""')}"`).join(",")).join("\n"),"text/csv")}

function splitTerms(value,kind){const separator=kind==="authors"?/;|\sand\s/i:/[;,|]/;return [...new Set(String(value||"").split(separator).map(x=>x.trim()).filter(Boolean).map(x=>kind==="keywords"?x.toLowerCase():x))]}
function analysisArticles(sessionId,scope="deduplicated"){const deduplicated=state.articles.filter(a=>a.sessionId===sessionId&&!a.isDuplicate),screening=recordsForProject(state.screeningSessions).filter(s=>s.analysisSessionId===sessionId).at(-1);if(scope==="deduplicated"||!screening)return {arts:scope==="deduplicated"?deduplicated:[],screening};const acceptedIds=new Set(state.screeningDecisions.filter(d=>d.screeningSessionId===screening.id&&d.decision==="include").map(d=>d.articleId));if(scope==="screened")return {arts:deduplicated.filter(a=>acceptedIds.has(a.id)),screening};const finalIds=new Set(state.eligibilityDecisions.filter(d=>d.screeningSessionId===screening.id&&d.decision==="include").map(d=>d.articleId));return {arts:deduplicated.filter(a=>finalIds.has(a.id)),screening}}
function statsFor(sessionId,scope="deduplicated"){const {arts,screening}=analysisArticles(sessionId,scope),count=(map,key)=>{if(key)map[key]=(map[key]||0)+1};let years={},journals={},authors={},keywords={},sources={};arts.forEach(a=>{count(years,a.year);count(journals,a.journal||a.source);count(sources,a.source);splitTerms(a.authors,"authors").forEach(x=>count(authors,x));splitTerms(a.keywords,"keywords").forEach(x=>count(keywords,x))});const top=(o,n=Number.MAX_SAFE_INTEGER)=>Object.entries(o).sort((a,b)=>b[1]-a[1]||String(a[0]).localeCompare(String(b[0]))).slice(0,n);return {arts,screening,years:top(years).sort((a,b)=>+a[0]-+b[0]),journals:top(journals),authors:top(authors),keywords:top(keywords),sources:top(sources,10),citations:arts.reduce((s,a)=>s+(+a.citationCount||0),0)}}
function bars(data){const max=Math.max(1,...data.map(x=>x[1]));return `<div class="bars">${data.map(([l,v])=>`<div class="bar-row"><span title="${esc(l)}">${esc(l||"Não informado")}</span><div class="bar-track"><span style="width:${v/max*100}%"></span></div><b>${v}</b></div>`).join("")||`<p class="muted">Sem dados.</p>`}</div>`}
function annualChart(years){if(!years.length)return `<p class="muted">Sem anos válidos para representar.</p>`;const max=Math.max(...years.map(x=>x[1]),1);return `<div class="annual-chart" role="img" aria-label="Produção científica anual">${years.map(([year,count])=>`<div class="annual-column" title="${year}: ${count} publicação(ões)"><b>${count}</b><span style="height:${Math.max(8,count/max*150)}px"></span><small>${esc(year)}</small></div>`).join("")}</div>`}
function networkData(arts,kind,limit=18){const counts={},pairs={};arts.forEach(article=>{const terms=splitTerms(article[kind],kind);terms.forEach(t=>counts[t]=(counts[t]||0)+1);for(let i=0;i<terms.length;i++)for(let j=i+1;j<terms.length;j++){const key=[terms[i],terms[j]].sort().join("\u0001");pairs[key]=(pairs[key]||0)+1}});const labels=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,limit).map(x=>x[0]),allowed=new Set(labels),nodes=labels.map((label,i)=>{const angle=Math.PI*2*i/Math.max(labels.length,1)-Math.PI/2,ring=i%3,rx=260-ring*34,ry=165-ring*20;return {label,count:counts[label],x:450+Math.cos(angle)*rx,y:235+Math.sin(angle)*ry}}),byLabel=Object.fromEntries(nodes.map(n=>[n.label,n])),edges=Object.entries(pairs).map(([key,weight])=>{const [a,b]=key.split("\u0001");return {a,b,weight}}).filter(e=>allowed.has(e.a)&&allowed.has(e.b)).sort((a,b)=>b.weight-a.weight).slice(0,45);return {nodes,edges,byLabel}}
