function bindNetworkInteractions(){ $$(".science-network").forEach(svg=>{if(svg.dataset.interactive==="true")return;svg.dataset.interactive="true";const nodes=$$(".network-node",svg),edges=$$(".network-edge",svg),label=svg.nextElementSibling;const clear=()=>{svg.classList.remove("is-focused");nodes.forEach(n=>n.classList.remove("is-active","is-neighbor"));edges.forEach(e=>e.classList.remove("is-active"));if(label)label.textContent="Passe o mouse sobre um nó para destacar suas conexões."};const focus=node=>{const id=node.dataset.node,neighbors=new Set();svg.classList.add("is-focused");edges.forEach(edge=>{const active=edge.dataset.a===id||edge.dataset.b===id;edge.classList.toggle("is-active",active);if(active)neighbors.add(edge.dataset.a===id?edge.dataset.b:edge.dataset.a)});nodes.forEach(n=>{n.classList.toggle("is-active",n.dataset.node===id);n.classList.toggle("is-neighbor",neighbors.has(n.dataset.node))});if(label)label.innerHTML=`<b>${esc(node.dataset.label)}</b> · frequência ${node.dataset.count} · ${neighbors.size} conexão(ões)`};nodes.forEach(node=>{node.addEventListener("pointerenter",()=>focus(node));node.addEventListener("pointerleave",clear);node.addEventListener("focus",()=>focus(node));node.addEventListener("blur",clear);node.addEventListener("click",()=>focus(node));node.addEventListener("keydown",event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();focus(node)}})})})}
function bradfordAnalysis(journals){const rows=journals.filter(x=>x[0]),total=rows.reduce((sum,x)=>sum+x[1],0),target=total/3;let cumulative=0,zone=1;const classified=rows.map(([journal,count])=>{cumulative+=count;const row={journal,count,cumulative,zone};if(cumulative>=target*zone&&zone<3)zone++;return row}),zones=[1,2,3].map(z=>{const group=classified.filter(r=>r.zone===z);return {zone:z,journals:group.length,articles:group.reduce((s,r)=>s+r.count,0)}});return {total,classified,zones}}
