function thematicEvolution(arts){const dated=arts.filter(article=>Number.isInteger(+article.year)&&+article.year>0),years=dated.map(article=>+article.year);if(!years.length)return {dated:[],periods:[],terms:[],start:null,end:null};const start=Math.min(...years),end=Math.max(...years),span=end-start+1,bounds=Array.from({length:3},(_,index)=>{const from=start+Math.floor(index*span/3),to=index===2?end:start+Math.floor((index+1)*span/3)-1;return {index,from,to:Math.max(from,to),label:from===Math.max(from,to)?String(from):`${from}–${Math.max(from,to)}`,articles:[],counts:new Map()}});dated.forEach(article=>{const index=Math.min(2,Math.floor((+article.year-start)*3/span)),period=bounds[index];period.articles.push(article);splitTerms(article.keywords,"keywords").forEach(term=>period.counts.set(term,(period.counts.get(term)||0)+1))});const termMap=new Map();bounds.forEach(period=>period.counts.forEach((count,term)=>{const record=termMap.get(term)||{term,counts:[0,0,0],total:0,yearSum:0};record.counts[period.index]=count;record.total+=count;termMap.set(term,record)}));dated.forEach(article=>splitTerms(article.keywords,"keywords").forEach(term=>{const record=termMap.get(term);if(record)record.yearSum+=+article.year}));const terms=[...termMap.values()].map(record=>{const shares=record.counts.map((count,index)=>bounds[index].articles.length?count/bounds[index].articles.length:0),delta=shares[2]-shares[0],presence=record.counts.filter(Boolean).length,trend=presence===3?"Persistente":record.counts[2]>0&&record.counts[0]===0?"Emergente":record.counts[0]>0&&record.counts[2]===0?"Em declínio":delta>.05?"Em crescimento":delta<-.05?"Em declínio":"Estável";return {...record,averageYear:record.total?record.yearSum/record.total:start,shares,delta,presence,trend}}).sort((a,b)=>b.total-a.total||a.term.localeCompare(b.term));bounds.forEach(period=>period.top=[...period.counts].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0])).slice(0,10));return {dated,periods:bounds,terms,start,end}}
function temporalNetworkGraph(arts,evolution){const net=networkData(evolution.dated,"keywords",22);if(net.nodes.length<2)return `<div class="network-empty">Metadados insuficientes para formar a rede temática temporal.</div>`;const termInfo=Object.fromEntries(evolution.terms.map(term=>[term.term,term])),max=Math.max(...net.nodes.map(node=>node.count),1),edgeMax=Math.max(...net.edges.map(edge=>edge.weight),1),nodeIndex=Object.fromEntries(net.nodes.map((node,index)=>[node.label,index])),range=Math.max(1,evolution.end-evolution.start),color=year=>`hsl(${220-(year-evolution.start)/range*175} 72% 46%)`;return `<div class="network-wrap"><svg class="science-network temporal-network" viewBox="0 0 900 470" role="img" aria-label="Rede temática temporal"><g class="network-edges">${net.edges.map(edge=>{const a=net.byLabel[edge.a],b=net.byLabel[edge.b];return `<line class="network-edge" data-a="${nodeIndex[edge.a]}" data-b="${nodeIndex[edge.b]}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" style="stroke-width:${.7+edge.weight/edgeMax*3}"/>`}).join("")}</g><g class="network-nodes">${net.nodes.map((node,index)=>{const info=termInfo[node.label],year=info?.averageYear||evolution.start,radius=10+node.count/max*17;return `<g class="network-node" data-node="${index}" data-label="${esc(node.label)}" data-count="${node.count}" tabindex="0" role="button" aria-label="${esc(node.label)}, frequência ${node.count}, ano médio ${year.toFixed(1)}"><circle cx="${node.x}" cy="${node.y}" r="${radius}" fill="${color(year)}"><title>${esc(node.label)} — ${node.count} — ano médio ${year.toFixed(1)}</title></circle><text x="${node.x}" y="${node.y+radius+13}" text-anchor="middle">${esc(node.label.length>24?node.label.slice(0,22)+"…":node.label)}</text></g>`}).join("")}</g></svg><div class="network-focus-label" aria-live="polite">Passe o mouse sobre um nó para destacar suas conexões.</div><div class="temporal-color-legend"><span>${evolution.start} · temas anteriores</span><i></i><span>${evolution.end} · temas recentes</span></div><div class="network-legend"><span>Cor: ano médio das ocorrências.</span><span>Tamanho: frequência.</span><span>Linha: força de coocorrência.</span></div></div>`}
function thematicEvolutionView(arts){const evolution=thematicEvolution(arts);if(!evolution.dated.length)return `<div class="network-empty">Nenhum artigo possui ano válido para a análise temporal.</div>`;const undated=arts.length-evolution.dated.length,emerging=evolution.terms.filter(term=>term.trend==="Emergente"||term.trend==="Em crescimento").sort((a,b)=>b.delta-a.delta).slice(0,12),declining=evolution.terms.filter(term=>term.trend==="Em declínio").sort((a,b)=>a.delta-b.delta).slice(0,12),persistent=evolution.terms.filter(term=>term.trend==="Persistente").slice(0,12);return `<div class="temporal-summary"><span><b>${evolution.start}–${evolution.end}</b><small>intervalo analisado</small></span><span><b>${evolution.dated.length}</b><small>artigos com ano válido</small></span><span><b>${undated}</b><small>artigos fora da comparação</small></span><span><b>${evolution.terms.length}</b><small>termos acompanhados</small></span></div><div class="temporal-periods">${evolution.periods.map((period,index)=>`<section><span>Período ${index+1}</span><h3>${period.label}</h3><small>${period.articles.length} artigo(s)</small>${bars(period.top.slice(0,8))}</section>`).join("")}</div><section class="temporal-network-card"><h3>Rede temática em sobreposição temporal</h3>${temporalNetworkGraph(arts,evolution)}</section><div class="temporal-trends"><section><h3>Temas emergentes ou em crescimento</h3>${emerging.length?emerging.map(term=>`<span><b>${esc(term.term)}</b><small>${term.trend}</small></span>`).join(""):`<p class="muted">Nenhum tema classificado nesta categoria.</p>`}</section><section><h3>Temas persistentes</h3>${persistent.length?persistent.map(term=>`<span><b>${esc(term.term)}</b><small>${term.total} ocorrência(s)</small></span>`).join(""):`<p class="muted">Nenhum termo aparece nos três períodos.</p>`}</section><section><h3>Temas em declínio</h3>${declining.length?declining.map(term=>`<span><b>${esc(term.term)}</b><small>${term.trend}</small></span>`).join(""):`<p class="muted">Nenhum tema classificado nesta categoria.</p>`}</section></div><div class="notice"><b>Leitura metodológica:</b> crescimento e declínio são calculados pela variação da presença do termo por artigo entre o primeiro e o último período. A classificação é descritiva e depende da padronização das palavras-chave.</div>`}
